use glam::DVec3;
use ingetrazo_core::scene::Scene;
use ingetrazo_tools::pushpull::PushPullTool;
use serde_json::{Value,json};
fn main(){let args:Vec<_>=std::env::args().collect();let input:Value=serde_json::from_slice(&std::fs::read(&args[1]).unwrap()).unwrap();let mut rows=vec![];for case in input["cases"].as_array().unwrap(){let mut s=Scene::new();for face in case["source"].as_array().unwrap(){let mut ring=|v:&Value|v.as_array().unwrap().iter().map(|p|s.mesh.add_vertex(DVec3::new(p[0].as_f64().unwrap(),p[1].as_f64().unwrap(),p[2].as_f64().unwrap()))).collect::<Vec<_>>();let outer=ring(&face["vertices"]);let holes=face["holes"].as_array().unwrap().iter().map(&mut ring).collect();let f=s.mesh.add_face(outer,holes).unwrap();s.mesh.faces[f].attrs=serde_json::from_value(face["attrs"].clone()).unwrap();s.mesh.faces[f].interior=face["interior"].as_bool().unwrap_or(false);}let before=s.clone();let result=PushPullTool::extrude_face_with_options(&mut s,case["face"].as_u64().unwrap()as usize,case["distance"].as_f64().unwrap(),case["ctrl"].as_bool().unwrap());let faces=s.mesh.faces.iter().map(|f|json!({"vertices":f.vertices.iter().map(|&i|s.mesh.vertices[i].position.to_array()).collect::<Vec<_>>(),"holes":f.holes.iter().map(|r|r.iter().map(|&i|s.mesh.vertices[i].position.to_array()).collect::<Vec<_>>()).collect::<Vec<_>>(),"attrs":f.attrs,"interior":f.interior})).collect::<Vec<_>>();rows.push(json!({"name":case["name"],"error":result.err(),"atomic_on_error":s==before,"result":faces}));}std::fs::write(&args[2],serde_json::to_vec_pretty(&json!({"cases":rows})).unwrap()).unwrap();}
